def hex_to_rgb(h):
    """'#8B3A3F' or '8B3A3F' -> (139, 58, 63)."""
    h = h.lstrip("#")
    return (int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16))


def rgb_to_hex(rgb):
    return "%02X%02X%02X" % tuple(int(v) for v in rgb)


def _lin(c):
    c = c / 255.0
    return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4


def _gam(c):
    return 12.92 * c if c <= 0.0031308 else 1.055 * c ** (1.0 / 2.4) - 0.055


def _cbrt(v):
    return math.copysign(abs(v) ** (1.0 / 3.0), v)


def hex_to_oklab(h):
    r, g, b = [_lin(v) for v in hex_to_rgb(h)]
    l = _cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b)
    m = _cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b)
    s = _cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b)
    return (0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s,
            1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s,
            0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s)


def _oklab_to_linear(L, a, b):
    l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3
    m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3
    s = (L - 0.0894841775 * a - 1.2914855480 * b) ** 3
    return (4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
            -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
            -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s)


def hex_to_oklch(h):
    L, a, b = hex_to_oklab(h)
    return (L, math.hypot(a, b), math.degrees(math.atan2(b, a)) % 360.0)


def oklch_to_hex(L, C, H):
    """OKLCH -> hex. Out-of-gamut colours keep L and H and lose chroma (x0.98 per step) until they fit sRGB."""
    L = min(max(L, 0.0), 1.0)
    C = max(C, 0.0)
    for _ in range(400):
        lin = _oklab_to_linear(L, C * math.cos(math.radians(H)), C * math.sin(math.radians(H)))
        if min(lin) >= -1e-6 and max(lin) <= 1.0 + 1e-6:
            break
        C *= 0.98
    return rgb_to_hex([int(math.floor(255.0 * _gam(min(max(v, 0.0), 1.0)) + 0.5)) for v in lin])


def oklab_to_hex(L, a, b):
    return oklch_to_hex(L, math.hypot(a, b), math.degrees(math.atan2(b, a)) % 360.0)


def mix(h1, h2, t):
    """Straight line in OKLab from h1 (t = 0) to h2 (t = 1)."""
    p, q = hex_to_oklab(h1), hex_to_oklab(h2)
    return oklab_to_hex(*[p[i] + (q[i] - p[i]) * t for i in range(3)])


def neutral_of(h):
    """The grey with the same OKLab lightness."""
    return oklab_to_hex(hex_to_oklab(h)[0], 0.0, 0.0)


def tones(h, rule=None):
    """3D tones of a colour used as a roof (its plan colour): roof, lit face, shade face, outline.
    rule = (lit L, lit C, shade L, shade C, outline L, outline C) multipliers in OKLCH; hue is kept."""
    r = rule or RAMP_RULE
    L, C, H = hex_to_oklch(h)
    return {"roof": h.lstrip("#").upper(), "lit": oklch_to_hex(L * r[0], C * r[1], H),
            "shade": oklch_to_hex(L * r[2], C * r[3], H), "outline": oklch_to_hex(L * r[4], C * r[5], H)}


def to_screen(x, y, z, theta=36.2, phi=32.9):
    """Parallel (axonometric) projection of diagram reference 2. theta: view direction in plan, degrees anticlockwise
    from the plan x axis; phi: degrees below horizontal. Returns (u right, v up, depth: larger = farther).
    Visible walls for 0 < theta < 90: the -x face (lit, appears left) and the -y face (shade, appears right)."""
    t, p = math.radians(theta), math.radians(phi)
    d = x * math.cos(t) + y * math.sin(t)
    return (x * math.sin(t) - y * math.cos(t), d * math.sin(p) + z * math.cos(p), d * math.cos(p) - z * math.sin(p))


def rgb(name_or_hex):
    """(r, g, b) 0-255 of a CORE role name or a hex string."""
    return hex_to_rgb(CORE.get(name_or_hex, name_or_hex))


def scheme(diagram_id):
    return list(SCHEMES[diagram_id]['topics'])


def tones_of(h):
    """Precomputed tones when available (identical to tones(h))."""
    h = h.lstrip('#').upper()
    return dict(TONES[h]) if h in TONES else tones(h)


def mp(key, step='light'):
    """A masterplan colour: mp('park') is the park fill, mp('park', 'dark') its edge and tag."""
    return MASTERPLAN[key][step]


def study(layer):
    """Line and label colour of a study-area layer (its owner's); other layers get the fallback ink."""
    return STUDY_AREA[layer]['line'] if layer in STUDY_AREA else STUDY_AREA_STYLE['fallback']
